import numpy as np

def relu(x):
    return np.maximum(0, x)

def sigmoid(x):
    return 1 / (1 + np.exp(-np.clip(x, -500, 500)))

def softmax(x):
    x_max = np.max(x, keepdims=True)
    exp_x = np.exp(x - x_max)
    return exp_x / np.sum(exp_x, keepdims=True)

def embed_features(X, embedding_weights):
    W, b = embedding_weights['W'], embedding_weights['b']
    if X.ndim == 1:
        X = X.reshape(1, -1)
    return relu(X @ W.T + b)

def relation_module(embedding_query, embedding_support, relation_weights):
    W1, b1, W2, b2 = relation_weights['W1'], relation_weights['b1'], relation_weights['W2'], relation_weights['b2']
    combined = np.concatenate([embedding_query, embedding_support])
    h = relu(W1 @ combined + b1)
    score = sigmoid(float(W2 @ h + b2))
    return score

def compute_prototypes(embeddings, labels, n_classes):
    dim = embeddings.shape[1]
    prototypes = np.zeros((n_classes, dim))
    for k in range(n_classes):
        mask = labels == k
        if mask.sum() > 0:
            prototypes[k] = np.mean(embeddings[mask], axis=0)
    return prototypes

def relation_classify(query_embedding, support_embeddings, support_labels, relation_weights, n_way):
    prototypes = compute_prototypes(support_embeddings, support_labels, n_way)
    scores = np.zeros(n_way)
    for k in range(n_way):
        scores[k] = relation_module(query_embedding, prototypes[k], relation_weights)
    return np.argmax(scores), scores

def relation_loss(query_embedding, query_label, support_embeddings, support_labels, relation_weights, n_way):
    prototypes = compute_prototypes(support_embeddings, support_labels, n_way)
    scores = np.zeros(n_way)
    for k in range(n_way):
        scores[k] = relation_module(query_embedding, prototypes[k], relation_weights)
    probs = softmax(scores)
    loss = -np.log(probs[query_label] + 1e-10)
    return loss

if __name__ == "__main__":
    np.random.seed(42)
    embedding_dim = 32
    n_way = 5
    relation_weights = {
        'W1': np.random.randn(16, embedding_dim * 2) * 0.1,
        'b1': np.zeros(16),
        'W2': np.random.randn(1, 16) * 0.1,
        'b2': np.zeros(1)
    }
    support_embeddings = np.random.randn(n_way * 5, embedding_dim)
    support_labels = np.repeat(np.arange(n_way), 5)
    query_embedding = np.random.randn(embedding_dim)
    pred, scores = relation_classify(query_embedding, support_embeddings, support_labels, relation_weights, n_way)
    print(f"Predicted class: {pred}")
    print(f"Relation scores: {scores}")
    loss = relation_loss(query_embedding, 0, support_embeddings, support_labels, relation_weights, n_way)
    print(f"Relation loss: {loss:.4f}")
